// Cada etapa usa uma pista do cenário para orientar a próxima ação.
function sala(cenario, etapas) {
  return {
    cenario,
    puzzles: etapas.map((etapa) => {
      if (!Array.isArray(etapa)) return etapa;
      const [pergunta, certa, primeira, segunda, dica, explicacao] = etapa;
      return { tipo: "multipla", pergunta, opcoes: [certa, primeira, segunda], correta: 0, dica, explicacao };
    }),
  };
}

